(() => {
  const app = document.querySelector('#app');
  if (!app) return;
  const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#039;' }[char]));
  const money = value => `PKR ${Number(value || 0).toLocaleString()}`;
  const date = value => value ? new Date(value).toLocaleDateString() : 'Not available';
  const toast = message => { const node = document.querySelector('#toast'); if (node) { node.textContent = message; node.classList.add('show'); setTimeout(() => node.classList.remove('show'), 2600); } };
  const api = async (path, options = {}) => { const response = await fetch(`/api${path}`, { headers: { 'Content-Type': 'application/json' }, ...options }); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error || 'Request failed.'); return body; };
  const status = value => `<span class="admin-status admin-status-${String(value || '').toLowerCase()}">${esc(value || 'Unknown')}</span>`;
  const avatar = user => `<span class="admin-inline-avatar">${esc(user.avatarInitials || String(user.name || user.phone || 'VP').split(/\s+/).filter(Boolean).map(part => part[0]).join('').slice(0, 2).toUpperCase())}</span>`;
  const proof = value => { if (!value) return '<span>Not provided</span>'; const safe = esc(value); return String(value).startsWith('data:image/') ? `<a class="admin-proof-preview" href="${safe}" target="_blank" rel="noopener"><img src="${safe}" alt="Payment proof"></a>` : `<a href="${safe}" target="_blank" rel="noopener">View payment proof</a>`; };
  const nav = [['overview','Overview','▦'],['users','Users','◉'],['devices','Devices','⌁'],['plans','Plans','▤'],['orders','Orders','▣'],['withdrawals','Withdrawals','↗'],['payments','Payment Methods','▰'],['settings','Settings / Profile','⚙']];
  let section = location.hash.slice(1) || 'overview';
  let data = { users:[], devices:[], plans:[], orders:[], withdrawals:[], methods:[], settings:{} };
  const root = () => document.querySelector('.admin-console');
  const load = async () => { const [users, devices, plans, orders, withdrawals, methods, settings] = await Promise.all([api('/admin/users'), api('/admin/devices'), api('/admin/plans'), api('/admin/orders'), api('/admin/withdrawals'), api('/admin/payment-methods'), api('/admin/settings')]); data = { users:users.users, devices:devices.devices, maxAccountsPerDevice:devices.maxAccountsPerDevice, plans:plans.plans, orders:orders.orders, withdrawals:withdrawals.withdrawals, methods:methods.methods, settings:settings.settings }; };
  const header = (eyebrow, title, copy, action = '') => `<div class="admin-page-header"><div><span class="admin-eyebrow">${eyebrow}</span><h1>${title}</h1><p>${copy}</p></div>${action}</div>`;
  const empty = text => `<div class="admin-empty"><strong>${text}</strong><span>There are no matching records.</span></div>`;
  const table = (heads, rows, emptyText) => rows ? `<div class="admin-table-wrap"><table class="admin-table"><thead><tr>${heads.map(head => `<th>${head}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>` : empty(emptyText);
  const modal = content => { document.querySelector('.admin-modal-backdrop')?.remove(); document.body.insertAdjacentHTML('beforeend', `<div class="admin-modal-backdrop"><div class="admin-modal">${content}<button class="admin-modal-close" data-action="close-modal">×</button></div></div>`); };
  const metrics = () => { const pendingOrders = data.orders.filter(item => item.status === 'Pending').length; const approvedOrders = data.orders.filter(item => ['Approved','Processing','Completed'].includes(item.status)).length; const pendingWithdrawals = data.withdrawals.filter(item => String(item.status).toLowerCase() === 'pending').length; const processed = data.withdrawals.filter(item => ['approved','processing','completed'].includes(String(item.status).toLowerCase())).reduce((total, item) => total + Number(item.amount || 0), 0); return `<section class="admin-metrics"><article class="admin-metric blue"><span>Total users</span><strong>${data.users.length}</strong><small>Real registered accounts</small></article><article class="admin-metric green"><span>Active plans</span><strong>${data.plans.filter(item => item.active).length}</strong><small>${data.plans.length} total plans</small></article><article class="admin-metric amber"><span>Pending orders</span><strong>${pendingOrders}</strong><small>${approvedOrders} approved or processing</small></article><article class="admin-metric red"><span>Pending withdrawals</span><strong>${pendingWithdrawals}</strong><small>${money(processed)} processed</small></article></section>`; };
  const overview = () => `${header('Platform overview','Good morning, Admin','A clear view of VercelPlans operations.','<button class="admin-button admin-button-quiet" data-action="refresh">↻ Refresh</button>')}${metrics()}<div class="admin-grid-2"><section class="admin-panel"><div class="admin-panel-heading"><div><h2>Recent orders</h2><span>Latest customer activity</span></div><a href="#orders">View all</a></div>${table(['Customer','Plan','Amount','Status','Date'], data.orders.slice(0,5).map(item => `<tr><td><strong>${esc(item.phone)}</strong><small>#${item.id}</small></td><td>${esc(item.plan_name)}</td><td>${money(item.investment)}</td><td>${status(item.status)}</td><td>${date(item.created_at)}</td></tr>`).join(''), 'No orders yet')}</section><section class="admin-panel"><div class="admin-panel-heading"><div><h2>Recent withdrawals</h2><span>Latest payout activity</span></div><a href="#withdrawals">View all</a></div>${table(['Customer','Wallet','Account','Amount','Status','Date'], data.withdrawals.slice(0,5).map(item => `<tr><td>${esc(item.phone)}</td><td>${esc(item.wallet || '—')}</td><td>${esc(item.account_number || '—')}<small>${esc(item.account_holder || '')}</small></td><td>${money(item.amount)}</td><td>${status(item.status)}</td><td>${date(item.created_at)}</td></tr>`).join(''), 'No withdrawals yet')}</section></div>`;
  const users = () => { const q = (root()?.querySelector('[data-search]')?.value || '').toLowerCase(); const rows = data.users.filter(item => `${item.id} ${item.phone} ${item.name} ${item.email} ${item.role} ${item.referral_code}`.toLowerCase().includes(q)); return `${header('Accounts','Users','Search, review, and manage every registered account.','<div class="admin-toolbar"><input class="admin-search" data-search placeholder="Search name, phone, email, or code"><button class="admin-button admin-button-primary" data-action="new-user">+ Create user</button></div>')}<section class="admin-panel">${table(['User','Contact','Status','Balance','Referral','Devices / plans','Actions'], rows.map(item => `<tr><td><strong>${esc(item.name || `User #${item.id}`)}</strong><small>#${item.id} · ${esc(item.phone)}</small></td><td>${esc(item.email || 'No email')}<small>Registered ${date(item.created_at)}</small></td><td>${status(item.status || 'active')}</td><td><strong>${money(item.balance)}</strong></td><td><strong>${esc(item.referral_code || 'Not assigned')}</strong><small>${Number(item.total_referrals || 0)} referrals · ${money(item.referral_earnings)} earned</small></td><td>${Number(item.device_count || 0)} devices<small>${Number(item.active_plan_count || 0)} active plans</small></td><td><div class="admin-actions"><button class="admin-button admin-button-small" data-action="view-user" data-id="${item.id}">View</button>${item.status !== 'deleted' ? `<button class="admin-button admin-button-small" data-action="manage-user" data-id="${item.id}">Edit</button>${item.role !== 'admin' ? `<button class="admin-button admin-button-danger admin-button-small" data-action="delete-user" data-id="${item.id}">Delete</button>` : ''}` : '<span class="admin-status admin-status-deleted">Deleted</span>'}</div></td></tr>`).join(''), 'No users found')}</section>`; };
  const devices = () => { const rows = data.devices || []; return `${header('Security','Devices','Review account relationships and grant additional registrations when appropriate.')}<section class="admin-panel"><div class="admin-device-summary">Global limit: <strong>${Number(data.maxAccountsPerDevice || 1)} accounts per device</strong></div>${table(['Device identifier','Accounts','Users','Exception','Actions'], rows.map(item => { const limit = Number(data.maxAccountsPerDevice || 1) + (item.exception_allowed ? Number(item.additional_accounts || 0) : 0); return `<tr><td><strong>${esc(item.device_hash)}</strong><small>First registered ${date(item.first_registered_at)}</small></td><td><strong>${Number(item.account_count || 0)}/${limit}</strong><small>${item.exception_allowed ? `+${Number(item.additional_accounts || 0)} granted` : 'Default limit'}</small></td><td>${item.users?.length ? item.users.map(user => `<span class="admin-device-user">${esc(user.name || user.phone)} · ${esc(user.status)}</span>`).join('') : '<span>Historical registration</span>'}</td><td>${item.exception_allowed ? status('Allowed') : status('Restricted')}<small>${esc(item.exception_reason || '')}</small></td><td><button class="admin-button admin-button-small" data-action="device-exception" data-hash="${esc(item.device_hash)}" data-extra="${Number(item.additional_accounts || 1)}">${item.exception_allowed ? 'Adjust grant' : 'Grant access'}</button></td></tr>`; }).join(''), 'No registered devices found')}</section>`; };
  const plans = () => `${header('Catalog','Plans','Manage active earning plans and projected returns.','<button class="admin-button admin-button-primary" data-action="new-plan">+ Add plan</button>')}<section class="admin-panel">${table(['Plan','Investment','Projected return','Duration','Status','Actions'], data.plans.map(item => `<tr><td><strong>${esc(item.name)}</strong><small>${esc(item.description)}</small></td><td>${money(item.investment)}</td><td><strong>${money(item.daily_return)}</strong> daily<small>${Number(item.return_rate || 0)}% rate · ${money(item.total_return)} projected profit</small></td><td>${item.duration_days} days</td><td>${status(item.active ? 'Active' : 'Inactive')}</td><td><div class="admin-actions"><button class="admin-button admin-button-small" data-action="edit-plan" data-id="${item.id}">Edit</button><button class="admin-button admin-button-small" data-action="toggle-plan" data-id="${item.id}" data-active="${item.active}">${item.active ? 'Deactivate' : 'Activate'}</button><button class="admin-button admin-button-danger admin-button-small" data-action="delete-plan" data-id="${item.id}">Delete</button></div></td></tr>`).join(''), 'No plans found')}</section>`;
  const orders = () => { const q = (root()?.querySelector('[data-search]')?.value || '').toLowerCase(); const filter = root()?.querySelector('[data-filter]')?.value || 'all'; const rows = data.orders.filter(item => `${item.id} ${item.phone} ${item.plan_name}`.toLowerCase().includes(q) && (filter === 'all' || item.status === filter)); const options = ['Pending','Approved','Rejected','Processing','Completed'].map(item => '<option ' + (filter === item ? 'selected' : '') + '>' + item + '</option>').join(''); const toolbar = '<div class="admin-toolbar"><input class="admin-search" data-search placeholder="Search orders"><select class="admin-select" data-filter><option value="all">All statuses</option>' + options + '</select></div>'; const body = rows.map(item => `<tr><td><strong>#${item.id}</strong></td><td>${esc(item.phone)}</td><td>${esc(item.plan_name)}</td><td>${money(item.investment)}</td><td>${esc(item.payment_method || 'Unavailable')}</td><td>${status(item.status)}</td><td>${date(item.created_at)}</td><td>${proof(item.payment_proof)}<br><button class="admin-button admin-button-small" data-action="view-order" data-id="${item.id}">View</button></td></tr>`).join(''); return header('Operations','Orders','Review payments and approve customer plan purchases.',toolbar) + '<section class="admin-panel">' + table(['Order','Customer','Plan','Amount','Payment','Status','Date','Actions'], body, 'No matching orders') + '</section>'; };
  const withdrawals = () => { const q = (root()?.querySelector('[data-search]')?.value || '').toLowerCase(); const filter = root()?.querySelector('[data-filter]')?.value || 'all'; const rows = data.withdrawals.filter(item => `${item.id} ${item.phone} ${item.wallet}`.toLowerCase().includes(q) && (filter === 'all' || String(item.status).toLowerCase() === filter)); const toolbar = '<div class="admin-toolbar"><input class="admin-search" data-search placeholder="Search withdrawals"><select class="admin-select" data-filter><option value="all">All statuses</option><option>pending</option><option>processing</option><option>completed</option><option>rejected</option></select></div>'; const body = rows.map(item => `<tr><td><strong>#${item.id}</strong></td><td>${esc(item.phone)}</td><td>${esc(item.wallet)}</td><td>${esc(item.account_number)}</td><td>${money(item.amount)}</td><td>${status(item.status)}</td><td>${date(item.created_at)}</td><td><button class="admin-button admin-button-small" data-action="view-withdrawal" data-id="${item.id}">View</button></td></tr>`).join(''); return header('Payouts','Withdrawals','Review and process customer payout requests.',toolbar) + '<section class="admin-panel">' + table(['Request','Customer','Wallet','Account','Amount','Status','Date','Actions'], body, 'No matching withdrawals') + '</section>'; };
  const payments = () => `${header('Configuration','Payment methods','Control where customers send their payment.','<button class="admin-button admin-button-primary" data-action="new-payment">+ Add method</button>')}<section class="admin-panel admin-payment-grid">${data.methods.map(item => `<article class="admin-payment-card"><div class="admin-payment-icon">${esc(item.name).slice(0,1)}</div><div><h2>${esc(item.name)}</h2><p>${esc(item.details || 'No payment instructions configured.')}</p>${status(item.enabled ? 'Enabled' : 'Disabled')}</div><div class="admin-actions"><button class="admin-button admin-button-small" data-action="edit-payment" data-id="${item.id}">Edit</button><button class="admin-button admin-button-small" data-action="toggle-payment" data-id="${item.id}" data-enabled="${item.enabled}">${item.enabled ? 'Disable' : 'Enable'}</button><button class="admin-button admin-button-danger admin-button-small" data-action="delete-payment" data-id="${item.id}">Delete</button></div></article>`).join('')}</section>`;
  const settings = () => `${header('Configuration','Platform settings','These values are stored in Neon and enforced by the backend.')}<section class="admin-panel admin-settings"><form data-form="admin-settings"><label>Maximum accounts per device<input name="max_accounts_per_device" type="number" min="1" max="20" value="${Number(data.settings.max_accounts_per_device ?? 1)}" required><small>Registration is rejected when this limit is reached.</small></label><label>Minimum Withdrawal Amount<input name="minimum_withdrawal_amount" type="number" min="0" value="${Number(data.settings.minimum_withdrawal_amount ?? 500)}" required></label><label>Referral Reward Amount<input name="referral_reward_amount" type="number" min="0" value="${Number(data.settings.referral_reward_amount ?? 80)}" required></label><label>Daily Task Count<input name="daily_task_count" type="number" min="1" value="${Number(data.settings.daily_task_count ?? 10)}" required></label><label>Daily Task Reward<input name="daily_task_reward_amount" type="number" min="0" value="${Number(data.settings.daily_task_reward_amount ?? 20)}" required></label><label><input name="referral_system_enabled" type="checkbox" ${data.settings.referral_system_enabled ? 'checked' : ''}> Referral system enabled</label><label><input name="withdrawal_system_enabled" type="checkbox" ${data.settings.withdrawal_system_enabled ? 'checked' : ''}> Withdrawal system enabled</label><label><input name="daily_tasks_enabled" type="checkbox" ${data.settings.daily_tasks_enabled ? 'checked' : ''}> Daily tasks enabled</label><label><input name="daily_profit_enabled" type="checkbox" ${data.settings.daily_profit_enabled ? 'checked' : ''}> Daily plan profits enabled</label><button class="admin-button admin-button-primary">Save platform settings</button></form><button class="admin-button admin-button-danger" data-action="logout">Log out</button></section>`;
  const page = () => section === 'users' ? users() : section === 'devices' ? devices() : section === 'plans' ? plans() : section === 'orders' ? orders() : section === 'withdrawals' ? withdrawals() : section === 'payments' ? payments() : section === 'settings' ? settings() : overview();
  const render = () => { const node = root(); if (!node) return; node.querySelector('[data-admin-content]').innerHTML = page(); if (section === 'settings') node.querySelector('[data-form="admin-settings"]')?.insertAdjacentHTML('afterend', `<form class="admin-settings admin-settings-secondary" data-form="account-creation-settings"><label>Account Creation Bonus<input name="account_creation_reward_amount" type="number" min="0" value="${Number(data.settings.account_creation_reward_amount ?? 0)}" required><small>Paid immediately to each newly registered account. Set the amount above 0 to enable it.</small></label><button class="admin-button admin-button-primary">Save account bonus</button></form>`); node.querySelectorAll('.admin-nav-link').forEach(link => link.classList.toggle('active', link.dataset.section === section)); bind(); };
  const renderWithControlState = () => { const active = document.activeElement; if (!active?.matches?.('input[data-search],select[data-filter]')) return render(); const selector = active.matches('input[data-search]') ? 'input[data-search]' : 'select[data-filter]'; const value = active.value; const selectionStart = active.selectionStart; const selectionEnd = active.selectionEnd; render(); const replacement = root()?.querySelector(selector); if (!replacement) return; replacement.value = value; replacement.focus(); if (selectionStart !== null && replacement.setSelectionRange) replacement.setSelectionRange(selectionStart, selectionEnd); };
  document.addEventListener('input', event => { if (event.target.matches?.('input[data-search]')) { event.stopImmediatePropagation(); renderWithControlState(); } }, true);
  document.addEventListener('change', event => { if (event.target.matches?.('select[data-filter]')) { event.stopImmediatePropagation(); renderWithControlState(); } }, true);
  const editForm = (type, item) => { const isPlan = type === 'plan'; const rate = Number(item?.return_rate || (Number(item?.daily_return || 0) / Number(item?.investment || 1) * 100)); return `<form data-form="${type}-modal" data-id="${item?.id || ''}" ${isPlan ? 'data-plan-calculator' : ''}><h2>${item ? `Edit ${isPlan ? 'plan' : 'payment method'}` : `Add ${isPlan ? 'plan' : 'payment method'}`}</h2>${isPlan ? `<label>Plan name<input name="name" placeholder="Plan name" value="${esc(item?.name)}" required></label><label>Investment amount<input name="investment" type="number" min="1" placeholder="Investment" value="${item?.investment || ''}" required></label><label>Profit / return rate (%)<input name="rate" type="number" min="0" step="0.01" placeholder="e.g. 5" value="${rate || ''}" required></label><label>Duration in days<input name="durationDays" type="number" min="1" placeholder="Duration days" value="${item?.duration_days || ''}" required></label><label>Calculated daily profit<input name="dailyReturn" type="number" value="${item?.daily_return || ''}" readonly></label><label>Calculated projected profit<input name="totalReturn" type="number" value="${item?.total_return || ''}" readonly></label><textarea name="description" placeholder="Description">${esc(item?.description)}</textarea>` : `<label>Payment method name<input name="name" placeholder="Payment method name" value="${esc(item?.name)}" required></label><label>Payment instructions<textarea name="details" placeholder="Payment number / instructions" required>${esc(item?.details)}</textarea></label>`}<button class="admin-button admin-button-primary">Save changes</button></form>`; };
  const calculatePlanValues = form => { if (!form?.matches('[data-plan-calculator]')) return; const investment = Number(form.elements.investment?.value || 0); const rate = Number(form.elements.rate?.value || 0); const duration = Number(form.elements.durationDays?.value || 0); const dailyReturn = Math.round(investment * rate / 100); if (form.elements.dailyReturn) form.elements.dailyReturn.value = dailyReturn || ''; if (form.elements.totalReturn) form.elements.totalReturn.value = dailyReturn * duration || ''; };
  const open = content => { document.querySelector('.admin-modal-backdrop')?.remove(); document.body.insertAdjacentHTML('beforeend', `<div class="admin-modal-backdrop"><div class="admin-modal">${content}<button class="admin-modal-close" data-action="close-modal">×</button></div></div>`); calculatePlanValues(document.querySelector('[data-plan-calculator]')); };
  const bind = () => { const node = root(); node.querySelector('[data-action="refresh"]')?.addEventListener('click', async () => { await refresh(); toast('Dashboard refreshed.'); }); node.querySelectorAll('input[data-search],select[data-filter]').forEach(input => input.addEventListener('input', render)); node.querySelectorAll('[data-action="new-plan"]').forEach(button => button.addEventListener('click', () => open(editForm('plan')))); node.querySelectorAll('[data-action="edit-plan"]').forEach(button => button.addEventListener('click', () => open(editForm('plan', data.plans.find(item => item.id === Number(button.dataset.id)))))); node.querySelectorAll('[data-action="new-payment"]').forEach(button => button.addEventListener('click', () => open(editForm('payment')))); node.querySelectorAll('[data-action="edit-payment"]').forEach(button => button.addEventListener('click', () => open(editForm('payment', data.methods.find(item => item.id === Number(button.dataset.id)))))); node.querySelectorAll('[data-action="edit-user"]').forEach(button => button.addEventListener('click', () => { const user = data.users.find(item => item.id === Number(button.dataset.id)); open(`<form data-form="user-modal" data-id="${user.id}"><h2>Edit user balance</h2><p>${esc(user.phone)} · User #${user.id}</p><input name="balance" type="number" min="0" value="${Number(user.balance || 0)}" required><button class="admin-button admin-button-primary">Save balance</button></form>`); })); node.querySelectorAll('[data-action="toggle-plan"]').forEach(button => button.addEventListener('click', async () => { await api(`/admin/plans/${button.dataset.id}`, { method:'PATCH', body:JSON.stringify({active:button.dataset.active !== 'true'}) }); await refresh(); })); node.querySelectorAll('[data-action="delete-plan"]').forEach(button => button.addEventListener('click', async () => { if (confirm('Delete this plan?')) { await api(`/admin/plans/${button.dataset.id}`, {method:'DELETE'}); await refresh(); } })); node.querySelectorAll('[data-action="toggle-payment"]').forEach(button => button.addEventListener('click', async () => { await api(`/admin/payment-methods/${button.dataset.id}`, {method:'PATCH',body:JSON.stringify({enabled:button.dataset.enabled !== 'true'})}); await refresh(); })); node.querySelectorAll('[data-action="delete-payment"]').forEach(button => button.addEventListener('click', async () => { if (confirm('Delete this payment method?')) { await api(`/admin/payment-methods/${button.dataset.id}`,{method:'DELETE'}); await refresh(); } })); node.querySelectorAll('[data-action="view-order"]').forEach(button => button.addEventListener('click', () => { const item=data.orders.find(row=>row.id===Number(button.dataset.id)); open(`<h2>Order #${item.id}</h2><p><strong>${esc(item.phone)}</strong> · ${esc(item.plan_name)}<br>Amount: ${money(item.investment)}<br>Payment: ${esc(item.payment_method)}<br>Transaction UID: ${esc(item.payment_reference || 'Not provided')}<br>Sender number: ${esc(item.payment_details || 'Not provided')}</p>${item.payment_proof?.startsWith('data:image/') ? `<img class="admin-proof-large" src="${esc(item.payment_proof)}" alt="Payment screenshot">` : '<p>No payment screenshot provided.</p>'}<div class="admin-modal-actions"><button class="admin-button admin-button-primary" data-action="approve" data-kind="order" data-id="${item.id}">Approve</button><button class="admin-button admin-button-danger" data-action="reject" data-kind="order" data-id="${item.id}">Reject</button></div>`); })); node.querySelectorAll('[data-action="view-withdrawal"]').forEach(button => button.addEventListener('click', () => { const item=data.withdrawals.find(row=>row.id===Number(button.dataset.id)); open(`<h2>Withdrawal #${item.id}</h2><p><strong>${esc(item.phone)}</strong><br>${money(item.amount)} via ${esc(item.wallet)}<br>Account: ${esc(item.account_number)}<br>Holder: ${esc(item.account_holder)}</p><div class="admin-modal-actions"><button class="admin-button admin-button-primary" data-action="approve" data-kind="withdrawal" data-id="${item.id}">Approve</button><button class="admin-button admin-button-danger" data-action="reject" data-kind="withdrawal" data-id="${item.id}">Reject</button></div>`); })); node.querySelectorAll('[data-action="logout"]').forEach(button => button.addEventListener('click', async () => { await api('/admin/logout',{method:'POST'}); location.reload(); })); node.querySelector('[data-form="admin-password"]')?.addEventListener('submit', async event => { event.preventDefault(); await api('/admin/password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget)))}); toast('Admin password updated.'); event.currentTarget.reset(); }); };
  const deletingUserIds = new Set();
  document.addEventListener('click', async event => { const button = event.target.closest('[data-action="delete-user"]'); if (!button) return; event.preventDefault(); event.stopImmediatePropagation(); const userId = Number(button.dataset.id); if (!Number.isInteger(userId) || deletingUserIds.has(userId)) return; if (!confirm('Delete this user and all of their account records? This cannot be undone.')) return; deletingUserIds.add(userId); const originalText = button.textContent; button.disabled = true; button.textContent = 'Deleting...'; try { await api(`/admin/users/${userId}`, { method: 'DELETE' }); data.users = data.users.filter(user => Number(user.id) !== userId); document.querySelector('.admin-modal-backdrop')?.remove(); render(); toast('User deleted.'); } catch (error) { button.disabled = false; button.textContent = originalText; toast(error.message); } finally { deletingUserIds.delete(userId); } }, true);
  document.addEventListener('click', async event => { const button = event.target.closest('[data-action="view-user"]'); if (!button) return; event.preventDefault(); event.stopImmediatePropagation(); try { const detail = await api(`/admin/users/${button.dataset.id}`); open(userDetail(detail)); } catch (error) { toast(error.message); } }, true);
  const refresh = async () => { try { await load(); render(); } catch (error) { toast(error.message); } };
  const build = async () => { try { await api('/admin/session'); app.innerHTML = `<div class="admin-console"><aside class="admin-sidebar"><div class="admin-brand"><span class="admin-brand-mark">V</span><span>VercelPlans<small>Admin Console</small></span></div><nav>${nav.map(([id,label,icon])=>`<a class="admin-nav-link" data-section="${id}" href="#${id}"><span>${icon}</span>${label}</a>`).join('')}</nav><button class="admin-nav-logout" data-action="logout">↪ Log out</button></aside><div class="admin-main"><header class="admin-topbar"><button class="admin-menu-toggle" data-action="toggle-menu">☰</button><div><strong>Admin Console</strong><span>Platform operations</span></div><span class="admin-session-pill">Secure session</span></header><main class="admin-content" data-admin-content><div class="admin-loading" aria-label="Loading admin console"><span class="loading-spinner"></span><div><strong>Preparing your workspace</strong><small>Loading operational data</small></div></div></main></div></div>`; await load(); render(); } catch { app.innerHTML = '<main class="auth-page admin-auth-page"><div class="auth-wrap"><div class="brand auth-brand"><span class="brand-mark">V</span>VercelPlans Admin</div><form class="auth-card" data-admin-login><h1>Admin Login</h1><p>Sign in with your administrator credentials.</p><div class="field"><label>Admin Email</label><input name="email" type="email" required placeholder="Admin email"></div><div class="field"><label>Admin Password</label><input name="password" type="password" required placeholder="Admin password"></div><button class="primary">Login</button></form></div></main>'; app.querySelector('form')?.addEventListener('submit', async event => { event.preventDefault(); try { await api('/admin/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget)))}); await build(); } catch(error) { toast(error.message); } }); } };
  document.addEventListener('click', async event => { const navLink = event.target.closest('.admin-nav-link'); if (navLink) { section = navLink.dataset.section; root()?.classList.remove('menu-open'); } if (event.target.closest('[data-action="toggle-menu"]')) root()?.classList.toggle('menu-open'); if (event.target.closest('[data-action="close-modal"]') || event.target.classList.contains('admin-modal-backdrop')) document.querySelector('.admin-modal-backdrop')?.remove(); const action = event.target.closest('[data-action="approve"],[data-action="reject"]'); if (action) { const kind=action.dataset.kind; const endpoint=kind==='order'?`/admin/orders/${action.dataset.id}`:`/admin/withdrawals/${action.dataset.id}`; await api(endpoint,{method:'PATCH',body:JSON.stringify({status:action.dataset.action==='approve'?'Approved':'Rejected'})}); document.querySelector('.admin-modal-backdrop')?.remove(); await refresh(); toast(`${kind} updated.`); } });
  document.addEventListener('submit', async event => { const form=event.target.closest('[data-form="plan-modal"],[data-form="payment-modal"],[data-form="user-modal"],[data-form="manage-user-modal"],[data-form="create-user-modal"],[data-form="admin-settings"]'); if (!form) return; event.preventDefault(); const values=Object.fromEntries(new FormData(form)); try { const type=form.dataset.form; const endpoint=type==='admin-settings'?'/admin/settings':type==='plan-modal'?(form.dataset.id?`/admin/plans/${form.dataset.id}`:'/admin/plans'):type==='payment-modal'?(form.dataset.id?`/admin/payment-methods/${form.dataset.id}`:'/admin/payment-methods'):type==='create-user-modal'?'/admin/users':`/admin/users/${form.dataset.id}`; const body=type==='user-modal'?{balance:Number(values.balance)}:type==='admin-settings'?{max_accounts_per_device:Number(values.max_accounts_per_device),minimum_withdrawal_amount:Number(values.minimum_withdrawal_amount),referral_reward_amount:Number(values.referral_reward_amount),daily_task_count:Number(values.daily_task_count),daily_task_reward_amount:Number(values.daily_task_reward_amount),referral_system_enabled:Boolean(values.referral_system_enabled),withdrawal_system_enabled:Boolean(values.withdrawal_system_enabled),daily_tasks_enabled:Boolean(values.daily_tasks_enabled),daily_profit_enabled:Boolean(values.daily_profit_enabled)}:values; await api(endpoint,{method:type==='admin-settings'?'PUT':type==='create-user-modal'?'POST':form.dataset.id?'PATCH':'POST',body:JSON.stringify(body)}); document.querySelector('.admin-modal-backdrop')?.remove(); await refresh(); toast(type==='create-user-modal'?'User created.':'Changes saved.'); } catch(error) { toast(error.message); } }, true);
  const userEditor = user => `<form data-form="manage-user-modal" data-id="${user.id}"><h2>Edit user account</h2><p>${avatar(user)} ${esc(user.fullName || user.name || 'User')} · ${esc(user.phone)}</p><label>First name<input name="firstName" value="${esc(user.firstName)}" maxlength="80" required></label><label>Last name<input name="lastName" value="${esc(user.lastName)}" maxlength="80" required></label><label>Email<input name="email" type="email" value="${esc(user.email)}" maxlength="160" placeholder="Optional email address"></label><label>Phone<input name="phone" value="${esc(user.phone)}" maxlength="20" required></label><label>Status<select name="status"><option ${user.status === 'active' ? 'selected' : ''}>active</option><option ${user.status === 'suspended' ? 'selected' : ''}>suspended</option></select></label><label>Balance adjustment<input name="balanceAdjustment" type="number" value="0"></label><label>Adjustment reason<input name="balanceReason" maxlength="200" placeholder="Required for financial changes"></label><label>New password<input name="password" type="password" minlength="7" autocomplete="new-password" placeholder="Leave blank to keep current password"></label><small class="admin-form-note">Existing passwords are never displayed or returned.</small><button class="admin-button admin-button-primary">Save changes</button></form>`;
  const detailTable = (heads, rows, emptyText) => rows.length ? table(heads.concat(heads[0] === 'Device' ? ['Actions'] : []), rows.join(''), emptyText) : empty(emptyText);
  const userDetail = detail => {
    const user = detail.user;
    const summary = detail.summary || {};
    const referralLink = `${location.origin}/register?ref=${encodeURIComponent(user.referralCode || '')}`;
    const planRows = detail.plans.map(item => `<tr><td><strong>${esc(item.plan_name)}</strong><small>#${item.id}</small></td><td>${money(item.investment)}</td><td>${Number(item.rate || 0)}%</td><td>${money(item.daily_profit)}</td><td>${Number(item.duration_days || 0)} days</td><td>${date(item.start_date)}<small>to ${date(item.end_date)}</small></td><td>${Number(item.days_completed || 0)} / ${Number(item.days_remaining || 0)}</td><td>${money(item.total_earned)}</td><td>${status(item.display_status)}</td></tr>`);
    const orderRows = detail.orders.map(item => `<tr><td><strong>#${item.id}</strong></td><td>${esc(item.plan_name)}</td><td>${money(item.investment)}</td><td>${esc(item.payment_method || 'Unavailable')}</td><td>${esc(item.payment_reference || item.payment_details || 'Not provided')}</td><td>${date(item.created_at)}</td><td>${status(item.status)}<small>${esc(item.admin_note || '')}</small></td><td>${proof(item.payment_proof)}<br><button class="admin-button admin-button-small" data-action="view-order" data-id="${item.id}">Open</button></td></tr>`);
    const withdrawalRows = detail.withdrawals.map(item => `<tr><td><strong>#${item.id}</strong></td><td>${money(item.amount)}</td><td>${esc(item.wallet)}</td><td>${esc(item.account_number)}<small>${esc(item.account_holder)}</small></td><td>${date(item.created_at)}</td><td>${status(item.status)}<small>${esc(item.rejection_reason || '')}</small></td></tr>`);
    const taskRows = detail.tasks.map(item => `<tr><td>${date(item.task_date)}</td><td>${esc(item.task_name)}</td><td>${esc(item.category || 'General')}</td><td>${money(item.reward_amount)}</td><td>${item.completed_at ? `${status('Completed')}<small>${date(item.completed_at)}</small>` : status('Pending')}</td></tr>`);
    const referralRows = detail.referrals.map(item => `<tr><td><strong>${esc(item.referred_name || item.referred_phone)}</strong><small>${esc(item.referred_phone)}</small></td><td>${esc(item.referred_email || 'No email')}</td><td>${date(item.created_at)}</td><td>${status(item.status)}</td><td>${money(item.reward_amount)}</td></tr>`);
    const activityRows = detail.activity.map(item => `<li><span class="admin-timeline-dot"></span><div><strong>${esc(item.type)}</strong><p>${esc(item.detail || 'Recorded account event')}</p><small>${date(item.date)}</small></div></li>`);
    const deviceRows = detail.devices.map(item => `<tr><td><strong>${esc(item.device_hash)}</strong></td><td>${date(item.created_at)}</td><td>${item.exception_allowed ? status('Allowed') : status('Restricted')}<small>${Number(detail.deviceLimit || 1)} base + ${Number(item.additional_accounts || 0)} extra accounts</small><small>${esc(item.exception_reason || '')}</small></td><td><button class="admin-button admin-button-small" data-action="detail-device-exception" data-user-id="${user.id}" data-hash="${esc(item.device_hash)}" data-extra="${Number(item.additional_accounts || 1)}" data-allowed="${item.exception_allowed}">Manage access</button></td></tr>`);
    const card = (label, value, tone = '') => `<article class="admin-user-stat ${tone}"><span>${label}</span><strong>${value}</strong></article>`;
    return `<div class="admin-user-detail-modal"><div class="admin-user-hero"><div class="admin-avatar">${esc((user.name || user.phone || 'U').slice(0, 1).toUpperCase())}</div><div class="admin-user-identity"><span class="admin-eyebrow">Customer account #${user.id}</span><h2>${esc(user.name || 'Unnamed customer')}</h2><p>${esc(user.phone)} · ${esc(user.email || 'No email')}</p><div>${status(user.status)} <span class="admin-user-meta">Referral ${esc(user.referralCode || 'Not assigned')}</span></div></div><div class="admin-user-actions"><button class="admin-button admin-button-primary" data-action="manage-detail-user" data-id="${user.id}">Edit user</button><button class="admin-button admin-button-quiet" data-action="manage-detail-user" data-id="${user.id}">Change password</button><button class="admin-button admin-button-quiet" data-action="toggle-detail-status" data-id="${user.id}" data-status="${esc(user.status)}">${user.status === 'active' ? 'Suspend' : 'Activate'}</button>${user.role !== 'admin' ? `<button class="admin-button admin-button-danger" data-action="delete-user" data-id="${user.id}">Delete user</button>` : ''}</div></div><div class="admin-user-meta-grid"><span><b>Registered</b>${date(user.created_at)}</span><span><b>Last activity</b>${date(user.last_login_at)}</span><span><b>Account status</b>${status(user.status)}</span><span><b>Referral link</b><input class="admin-detail-link" readonly value="${esc(referralLink)}"></span></div><nav class="admin-detail-tabs"><button class="active" data-detail-tab="overview">Overview</button><button data-detail-tab="plans">Plans</button><button data-detail-tab="referrals">Referrals</button><button data-detail-tab="orders">Orders</button><button data-detail-tab="withdrawals">Withdrawals</button><button data-detail-tab="tasks">Tasks & earnings</button><button data-detail-tab="activity">Activity</button></nav><section class="admin-detail-panel active" data-detail-panel="overview"><div class="admin-user-stat-grid">${card('Current balance', money(summary.balance), 'blue')}${card('Total earned', money(summary.total_earned), 'green')}${card('Active plan', esc(summary.active_plan))}${card('Daily profit', money(summary.daily_profit))}${card('Total referrals', summary.total_referrals)}${card('Approved referrals', summary.approved_referrals, 'green')}${card('Pending referrals', summary.pending_referrals, 'amber')}${card('Referral earnings', money(summary.referral_earnings), 'green')}${card('Total orders', summary.total_orders)}${card('Total withdrawals', money(summary.total_withdrawals))}${card('Account status', status(summary.account_status))}</div><div class="admin-detail-two-col"><div><h3>Account information</h3><dl class="admin-detail-list"><dt>Email</dt><dd>${esc(user.email || 'Not provided')}</dd><dt>Mobile</dt><dd>${esc(user.phone)}</dd><dt>Referral code</dt><dd>${esc(user.referralCode || 'Not assigned')}</dd><dt>Referred by</dt><dd>${detail.referredBy ? `${esc(detail.referredBy.referrer_name || detail.referredBy.referrer_phone)} · ${esc(detail.referredBy.referrer_phone)}` : 'Direct registration'}</dd></dl></div><div><h3>Devices</h3>${detailTable(['Device','Registered','Access'], deviceRows, 'No device records')}</div></div></section><section class="admin-detail-panel" data-detail-panel="plans"><h3>Plans and orders</h3>${detailTable(['Plan','Investment','Rate','Daily profit','Duration','Dates','Progress','Earned','Status'], planRows, 'No plans or orders')}</section><section class="admin-detail-panel" data-detail-panel="referrals"><div class="admin-detail-callout"><strong>${esc(user.referralCode || 'Not assigned')}</strong><span>${esc(referralLink)}</span><span>${detail.referredBy ? `Referred by ${esc(detail.referredBy.referrer_name || detail.referredBy.referrer_phone)}` : 'No referring account recorded'}</span></div><h3>Users referred by this account</h3>${detailTable(['User','Contact','Joined','Referral status','Reward'], referralRows, 'No referral relationships')}</section><section class="admin-detail-panel" data-detail-panel="orders"><h3>Order history</h3>${detailTable(['Order','Plan','Amount','Payment','Reference','Date','Status','Proof'], orderRows, 'No orders')}</section><section class="admin-detail-panel" data-detail-panel="withdrawals"><h3>Withdrawal history</h3>${detailTable(['Request','Amount','Method','Destination','Date','Status'], withdrawalRows, 'No withdrawals')}</section><section class="admin-detail-panel" data-detail-panel="tasks"><h3>Daily task activity</h3>${detailTable(['Date','Task','Category','Reward','Progress'], taskRows, 'No task records')}</section><section class="admin-detail-panel" data-detail-panel="activity"><h3>Account activity</h3>${activityRows.length ? `<ol class="admin-timeline">${activityRows.join('')}</ol>` : empty('No account activity')}</section></div>`;
  };
  document.addEventListener('click', async event => { const tab = event.target.closest('[data-detail-tab]'); if (tab) { const modalNode = tab.closest('.admin-user-detail-modal'); modalNode.querySelectorAll('[data-detail-tab]').forEach(item => item.classList.toggle('active', item === tab)); modalNode.querySelectorAll('[data-detail-panel]').forEach(item => item.classList.toggle('active', item.dataset.detailPanel === tab.dataset.detailTab)); return; } const viewButton = event.target.closest('[data-action="view-user"]'); if (viewButton) { try { const detail = await api(`/admin/users/${viewButton.dataset.id}`); open(userDetail(detail)); } catch (error) { toast(error.message); } return; } const manage = event.target.closest('[data-action="manage-detail-user"]'); if (manage) { const detailUser = data.users.find(item => item.id === Number(manage.dataset.id)); if (detailUser) open(userEditor(detailUser)); } const toggle = event.target.closest('[data-action="toggle-detail-status"]'); if (toggle && confirm(`${toggle.dataset.status === 'active' ? 'Suspend' : 'Activate'} this account?`)) { try { await api(`/admin/users/${toggle.dataset.id}`, { method:'PATCH', body:JSON.stringify({ status:toggle.dataset.status === 'active' ? 'suspended' : 'active' }) }); document.querySelector('.admin-modal-backdrop')?.remove(); await refresh(); toast('Account status updated.'); } catch (error) { toast(error.message); } } });
  document.addEventListener('click', event => { const button = event.target.closest('[data-action="detail-device-exception"]'); if (!button) return; open(`<form data-form="detail-device-exception-modal" data-hash="${button.dataset.hash}" data-user-id="${button.dataset.userId}"><h2>Manage device access</h2><p>${esc(button.dataset.hash)}</p><label>Additional accounts allowed<input name="additionalAccounts" type="number" min="0" max="50" value="${Number(button.dataset.extra || 0)}" required></label><small class="admin-form-note">This adds to the global device limit for this device. Set 0 to remove the exception.</small><label>Reason<textarea name="reason" required>Approved by admin</textarea></label><label><input name="allowed" type="checkbox" ${button.dataset.allowed === 'true' ? 'checked' : ''}> Exception enabled</label><button class="admin-button admin-button-primary">Save device access</button></form>`); });
  document.addEventListener('click', async event => { const button = event.target.closest('[data-action="manage-user"]'); if (button) { const user = data.users.find(item => item.id === Number(button.dataset.id)); if (!user) return; open(`<form data-form="manage-user-modal" data-id="${user.id}"><h2>Edit user account</h2><p>${esc(user.phone)} · User #${user.id}</p><label>Name<input name="name" value="${esc(user.name)}" maxlength="120"></label><label>Email<input name="email" type="email" value="${esc(user.email)}" maxlength="160"></label><label>Phone<input name="phone" value="${esc(user.phone)}" maxlength="20" required></label><label>Status<select name="status"><option ${user.status === 'active' ? 'selected' : ''}>active</option><option ${user.status === 'suspended' ? 'selected' : ''}>suspended</option></select></label><label>Balance adjustment<input name="balanceAdjustment" type="number" value="0"></label><label>Adjustment reason<input name="balanceReason" maxlength="200"></label><label>Reset password<input name="password" type="password" minlength="7" placeholder="Leave blank to keep current password"></label><button class="admin-button admin-button-primary">Save changes</button></form>`); return; } const deleteButton = event.target.closest('[data-action="delete-user"]'); if (!deleteButton || !confirm('Delete this user and all of their account records? This cannot be undone.')) return; try { await api(`/admin/users/${deleteButton.dataset.id}`, { method:'DELETE' }); await refresh(); toast('User deleted.'); } catch (error) { toast(error.message); } });
  document.addEventListener('submit', async event => { const form = event.target.closest('[data-form="manage-user-modal"]'); if (!form) return; event.preventDefault(); try { const values = Object.fromEntries(new FormData(form)); await api(`/admin/users/${form.dataset.id}`, { method:'PATCH', body:JSON.stringify(values) }); document.querySelector('.admin-modal-backdrop')?.remove(); await refresh(); toast('User updated.'); } catch (error) { toast(error.message); } });
  document.addEventListener('click', event => { const create = event.target.closest('[data-action="new-user"]'); if (create) open(`<form data-form="create-user-modal"><h2>Create customer account</h2><p class="admin-form-note">The password is hashed immediately and is never returned or stored in plaintext.</p><label>Name<input name="name" maxlength="120" required></label><label>Mobile number<input name="phone" pattern="03[0-9]{9}" maxlength="11" required></label><label>Email<input name="email" type="email" maxlength="160"></label><label>Temporary password<input name="password" type="password" minlength="7" autocomplete="new-password" required></label><label>Status<select name="status"><option>active</option><option>suspended</option></select></label><label>Device identifier (optional)<input name="deviceHash" placeholder="Assign an existing device"></label><button class="admin-button admin-button-primary">Create user</button></form>`); const device = event.target.closest('[data-action="device-exception"]'); if (device) open(`<form data-form="device-exception-modal" data-hash="${device.dataset.hash}"><h2>Grant device access</h2><p>${esc(device.dataset.hash)}</p><label>Additional registrations<input name="additionalAccounts" type="number" min="0" max="50" value="${Number(device.dataset.extra || 1)}" required></label><label>Reason<textarea name="reason" required>Approved by admin</textarea></label><label><input name="allowed" type="checkbox" checked> Exception enabled</label><button class="admin-button admin-button-primary">Save exception</button></form>`); });
  document.addEventListener('input', event => calculatePlanValues(event.target.closest('[data-plan-calculator]')));
  document.addEventListener('change', event => calculatePlanValues(event.target.closest('[data-plan-calculator]')));
  document.addEventListener('submit', async event => { const form = event.target.closest('[data-form="detail-device-exception-modal"]'); if (!form) return; event.preventDefault(); const values = Object.fromEntries(new FormData(form)); try { await api('/admin/device-exceptions', { method:'POST', body:JSON.stringify({ deviceHash:form.dataset.hash, userId:Number(form.dataset.userId), allowed:Boolean(values.allowed), additionalAccounts:Number(values.additionalAccounts), reason:values.reason }) }); document.querySelector('.admin-modal-backdrop')?.remove(); await refresh(); toast('User device access updated.'); } catch (error) { toast(error.message); } });
  document.addEventListener('submit', async event => { const form = event.target.closest('[data-form="device-exception-modal"]'); if (!form) return; event.preventDefault(); const values = Object.fromEntries(new FormData(form)); try { await api('/admin/device-exceptions', { method:'POST', body:JSON.stringify({ deviceHash:form.dataset.hash, allowed:Boolean(values.allowed), additionalAccounts:Number(values.additionalAccounts), reason:values.reason }) }); document.querySelector('.admin-modal-backdrop')?.remove(); await refresh(); toast('Device exception saved.'); } catch (error) { toast(error.message); } });
  document.addEventListener('submit', async event => { const form = event.target.closest('[data-form="account-creation-settings"]'); if (!form) return; event.preventDefault(); try { const values = Object.fromEntries(new FormData(form)); await api('/admin/settings', { method:'PUT', body:JSON.stringify({ account_creation_reward_amount:Number(values.account_creation_reward_amount) }) }); await refresh(); toast('Account creation reward saved.'); } catch (error) { toast(error.message); } });
  const detailAvatarObserver = new MutationObserver(() => { const heading = document.querySelector('.admin-user-detail-modal .admin-user-identity h2'); const node = document.querySelector('.admin-user-detail-modal .admin-avatar'); if (heading && node) { const parts = heading.textContent.trim().split(/\s+/).filter(Boolean); const initials = (parts.length > 1 ? `${parts[0][0]}${parts[parts.length - 1][0]}` : parts[0]?.slice(0, 2) || 'VP').toUpperCase(); if (node.textContent !== initials) node.textContent = initials; } document.querySelectorAll('[data-action="view-user"]').forEach(button => { const user = data.users.find(item => item.id === Number(button.dataset.id)); const identity = button.closest('tr')?.querySelector('td strong'); if (user && identity && !identity.previousElementSibling?.classList.contains('admin-inline-avatar')) identity.insertAdjacentHTML('beforebegin', avatar(user)); }); });
  detailAvatarObserver.observe(document.body, { childList:true, subtree:true });
  window.addEventListener('hashchange', () => { section=location.hash.slice(1)||'overview'; render(); });
  new MutationObserver(() => { if (location.pathname==='/admin-dashboard' && !root() && !app.querySelector('[data-admin-login]')) build(); }).observe(app,{childList:true});
  if (location.pathname==='/admin') history.replaceState({}, '', '/admin-dashboard');
  if (location.pathname==='/admin-dashboard') build();
})();
